window.harnessChunks["rows-205c04af03929df0.js"]=["<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T19:31:23+03:00\"><th scope=\"row\"><a href=\"https://github.com/google/adk-python\" target=\"_blank\" rel=\"noopener\">Google ADK</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/google/adk-python/tree/460715b6c62c8e9ab00931c502381ee0364e39b6\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 460715b6c62c8e9ab00931c502381ee0364e39b6\">460715b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: agents can autonomously select tools/actions and iterate from session/task feedback inside configured bounds.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: sequential/parallel/loop workflow structure and fan-out/fan-in are not sufficient evidence of interference regulation, anti-oscillation, or mutual constraint management among autonomous S1 units. The shallow S2=C interpretation is removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: workflow parents control execution topology, not whole-system current resources, priorities, capacity and commitments across multiple S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no distinct complementary audit channel with separate access/authority was established in the reviewed boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: workflow iteration and task planning concern present execution rather than prospective environment intelligence that changes organizational capability/strategy.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: instructions, tools, workflow topology and policies are application/developer supplied rather than owned by an autonomous ultimate policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/537ba0e97528304cd6cea563179885b8ac1edd46/assessments/google-adk.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 537ba0e97528304cd6cea563179885b8ac1edd46\">537ba0e &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-27T00:14:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/RUC-NLPIR/WebThinker\" target=\"_blank\" rel=\"noopener\">WebThinker</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-26\">2026-09-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/RUC-NLPIR/WebThinker/tree/db387eb3261de9b5e2db7d2d7fb20af2aceb7882\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision db387eb3261de9b5e2db7d2d7fb20af2aceb7882\">db387eb &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: execute a complete deep-research task by autonomously choosing and iterating reasoning, web search/page exploration, evidence synthesis and, in report mode, section writing/editing until an answer or report is produced. - Disturbance / variety regulated: incomplete or stale knowledge, uncertain search direction, irrelevant search results, inaccessible pages, missing report sections, newly discovered evidence, current-article incompleteness and bounded token/search budgets. - Decisive decision or feedback right: decide whether and what to search next, when to explore/click further, when enough evidence exists to continue reasoning or write, which report section/edit to request and when the current research work is complete. - Decision owner: the model-driven WebThinker reasoning path instantiated by the first-party runtime; nested explorer and auxiliary writer/reader/editor calls execute subordinate task-local decisions/functions. - Supporting / enforcement mechanisms: explicit search/click/write/check/edit markers, asynchronous search adapters, page fetching and caching, Deep Web Explorer loop, runtime history/article/document-memory state, BM25 document retrieval, interaction/token limits and auxiliary generation calls. - Closure path: user question/current trace -&gt; reasoning model selects a research action -&gt; first-party runtime executes search/exploration or report operation -&gt; web evidence/article change returns into the sequence -&gt; reasoning model chooses the next action -&gt; answer/report progresses until completion/limit. - Boundary reachability: scripts/runwebthinker.py and scripts/runwebthinkerreport.py are shipped documented entrypoints and directly instantiate the credited reasoning/action/feedback paths without requiring an adjacent benchmark or training controller. - Why this is / is not agent-owned: deterministic code executes selected calls and limits, while substantive search direction, follow-up exploration, report-operation selection and task completion choices are model-generated from live research state. - Evidence: README.md; scripts/runwebthinker.py; scripts/runwebthinkerreport.py; scripts/prompts/promptsreport.py. - Basis: explicit + structural. - Confidence: high. - Caveats: the operator supplies the top-level task, endpoints and search credentials; autonomy is assessed for the within-run operational choices, not for those parent configuration decisions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no qualifying inter-S1 disturbance-attenuation function is established at the declared boundary. - Disturbance / variety regulated: none qualifying; search planning, nested web exploration and auxiliary writing/editing coordinate steps of one research operation rather than attenuating interaction among distinct S1 units. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: shared sequence state, document memory, caches, semaphore/concurrency limits and task routing are present but are not sufficient for S2. - Closure path: no material S2-specific closure path established. - Why this is / is not agent-owned: there is no evidenced S2 organizational function to classify for ownership. - Evidence: scripts/runwebthinker.py; scripts/runwebthinkerreport.py. - Basis: structural absence. - Confidence: high. - Caveats: separate model roles and concurrent processing do not establish S2 without a concrete inter-operation disturbance and attenuating feedback relation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no separate superior inside-and-now regulator over multiple operational units is established. - Disturbance / variety regulated: current research progress and report completeness are regulated inside the same S1 operation. - Decisive decision or feedback right: no current-control right distinct from the S1&#39;s own search/reason/write/edit decisions is established. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: auxiliary search plan, interaction/token limits, report article state and batch concurrency are present but do not create a superior organizational control layer. - Closure path: no material S3-specific whole-system current-control path established. - Why this is / is not agent-owned: the main reasoning model has broad control over one research episode, but that is operational task control rather than S3 over a set of independently operating units. - Evidence: scripts/runwebthinker.py; scripts/runwebthinkerreport.py. - Basis: structural absence. - Confidence: high. - Caveats: the auxiliary search plan and central reasoning loop are not credited from component names or sequencing alone.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no qualifying complementary independent audit function is established. - Disturbance / variety regulated: report outline inspection and final structural cleanup can expose incompleteness/redundancy, but they remain ordinary in-band production/refinement of the same current report. - Decisive decision or feedback right: no independent reviewer forms a separate audit judgement over an operational claim and returns findings through a complementary access path. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: checkarticle outline return, auxiliary editor, final report editor and optional benchmark evaluation are present but do not satisfy the S3 independence/claim requirements. - Closure path: no material complementary-audit closure path established. - Why this is / is not agent-owned: there is no qualifying S3 function; auxiliary-model use alone does not create organizational audit independence. - Evidence: scripts/runwebthinkerreport.py; scripts/prompts/promptsreport.py; scripts/evaluate/ as an adjacent evaluation surface. - Basis: explicit + structural absence. - Confidence: high. - Caveats: the tool name checkarticle is specifically not treated as sufficient evidence for S3; its implementation returns the current article outline to the ordinary reasoning path rather than establishing an independent audit channel.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no separate prospective environmental-intelligence/adaptation function is established. - Disturbance / variety regulated: web uncertainty and missing knowledge are regulated for the current research question/report, not for WebThinker&#39;s future organizational posture or installed capability set. - Decisive decision or feedback right: none established for prospective adaptation beyond current-task search and synthesis. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: web search, page exploration, caches, document memory and README-described offline RL/DPO development do not establish runtime S4 closure. - Closure path: no material S4-specific prospective change path established. - Why this is / is not agent-owned: the runtime senses the external web extensively, but uses that information to complete the current task rather than to select/persist future organizational adaptation. - Evidence: README.md; scripts/runwebthinker.py; scripts/runwebthinkerreport.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: offline training/weight construction is adjacent development and is not imported into the inference harness boundary merely because the project describes progressive improvement through RL/DPO.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime authority over organizational identity, ultimate purpose or binding top-level policy is established. - Disturbance / variety regulated: none qualifying; the research question, model endpoints, credentials, search engine, limits and core instructions are externally supplied/configured. - Decisive decision or feedback right: no runtime actor can redefine WebThinker&#39;s ultimate mission or authoritatively close constitutional/policy conflicts. - Decision owner: user/operator and repository configuration outside the assessed autonomous runtime. - Supporting / enforcement mechanisms: static prompts, command-line arguments, search/token/interaction limits and model/LoRA selection constrain operation but are not runtime S5 ownership. - Closure path: no material S5-specific closure path established. - Why this is / is not agent-owned: WebThinker decides how to pursue the supplied research task, not what its ultimate identity/purpose should be. - Evidence: README.md; scripts/runwebthinker.py; scripts/runwebthinkerreport.py; scripts/prompts/promptsreport.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: highly directive system/prompt instructions can constrain an agent without transferring ultimate policy authority to the agent.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/15ef9148b7738daa5f7642bbeb03e2c87036b979/assessments/webthinker.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 15ef9148b7738daa5f7642bbeb03e2c87036b979\">15ef914 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"2\" data-assessment-at=\"2026-09-21T16:26:50Z\"><th scope=\"row\"><a href=\"https://github.com/truffle-ai/dexto\" target=\"_blank\" rel=\"noopener\">Dexto</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-21\">2026-09-21</time></td><td class=\"review-ref\"><a href=\"https://github.com/truffle-ai/dexto/tree/ac56fbfcd8e7a682fc0e96c690e5b6362980181d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ac56fbfcd8e7a682fc0e96c690e5b6362980181d\">ac56fbf &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform substantive user-directed work through a model-driven plan/action/tool/observation loop. - Disturbance / variety regulated: ambiguous goals, changing conversation context, tool/service observations, tool failures, queued user steering, context pressure and provider responses. - Decisive decision or feedback right: choose substantive next actions/tool calls and revise subsequent action from returned observations inside configured authority. - Decision owner: the running Dexto model agent. - Supporting / enforcement mechanisms: DextoAgent, ChatSession, first-party TurnExecutor, context/session persistence, ToolManager, approvals, queued steer/follow-up input, compaction, provider adapters and runtime state. - Closure path: user/host goal and current context → model step → selected tool/action → first-party execution/result → observation added to context → next model step or final result. - Boundary reachability: the shipped Dexto modes call DextoAgent/ChatSession, whose first-party TurnExecutor replaces the provider SDK&#39;s internal multi-step loop and explicitly controls one model step, tool execution and the next-step decision; no downstream harness implementation is required. - Why this is / is not agent-owned: runtime code validates, transports and enforces the loop, but removing the model actor removes the discretionary choice of substantive tool/action and adaptation to the returned observation. - Evidence: README.md, packages/core/src/agent/DextoAgent.ts, packages/core/src/session/chat-session.ts, packages/core/src/llm/executor/turn-executor.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: provider inference is execution substrate; it is not imported as organizational ownership.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: bound destructive interference among concurrently runnable child-agent S1 units sharing one parent/runtime capacity envelope. - Disturbance / variety regulated: excessive simultaneous sub-agent activity consuming finite parent/runtime capacity, producing unbounded parallel exploration or runaway subordinate execution. - Decisive decision or feedback right: determine the permitted concurrent-child envelope and therefore whether another child can enter the active set. - Decision owner: constructor/configuration owner; first-party runtime deterministically enforces the selected bound. - Supporting / enforcement mechanisms: maxConcurrentAgents, global maxAgents, per-parent grouping, canSpawn(), subordinate iteration caps, task timeouts and synchronous cleanup. - Closure path: active child count reaches the configured envelope → another spawn is rejected/withheld → existing child completes/stops and is removed → capacity becomes available → later child execution can proceed. - Boundary reachability: the shipped coding agent includes agent-spawner; the provider&#39;s schema and AgentSpawnerRuntime implement the per-parent bound, and exported AgentRuntime supplies the underlying first-party agent pool. The coordination primitive is therefore available in supported distribution without a downstream scheduler implementation. - Why this is / is not agent-owned: the standard model agent may choose when to invoke spawnagent, but it does not choose or revise the concurrency policy in response to inter-agent disturbance; deterministic runtime enforces a constructor-selected limit. - Evidence: README.md, agents/coding-agent/coding-agent.yml, packages/agent-management/src/tool-factories/agent-spawner/schemas.ts, packages/agent-management/src/tool-factories/agent-spawner/runtime.ts, packages/agent-management/src/runtime/AgentRuntime.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: generic delegation is not the witness; the credited S2 path is the explicit bounded shared-capacity relation across concurrently runnable subordinate S1 units. The standard distribution does not establish an autonomous actor that owns or revises this coordination decision. - Distinct S1 units: separately instantiated spawned DextoAgent child loops executing independent delegated tasks. - Inter-S1 disturbance: simultaneous child loops can exceed the configured safe/capacity envelope for one parent/runtime and create uncontrolled parallel subordinate activity. - Attenuating coordination relation: maxConcurrentAgents / maxAgents plus runtime admission checks cap the active child set; subordinate iteration/time limits further bound the disturbance. - Feedback into subsequent S1 behaviour: an attempted child does not enter execution when the cap is reached; completion/cleanup changes pool state so a later spawn can enter the active set. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the positive claim is tied to a concrete cross-unit concurrency disturbance and a first-party capacity attenuation path, not to the fact that tasks are delegated or messages/results are routed.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: expose current whole-pool visibility and lifecycle intervention over multiple Dexto operational agents for a higher-level controller. - Disturbance / variety regulated: changing active-agent population, running/error/stopped states, current task commitments and agents that need to be stopped or removed. - Decisive decision or feedback right: choose which agents to spawn, continue or stop based on the current pool/agent state. - Decision owner: not supplied autonomously by the constructor surface; a downstream controller/operator must exercise the exposed right. - Supporting / enforcement mechanisms: AgentPool, status transitions, grouping/filtering, spawnAgent, getAgent, listAgents, getStats, stopAgent and stopAll. - Closure path: current pool/status view → downstream supervisory decision → spawn/stop intervention → first-party lifecycle machinery changes the active pool → updated list/stats/status is available for the next decision. - Boundary reachability: AgentRuntime is exported as a first-party general-purpose multi-agent lifecycle manager and intentionally exposes pool visibility plus intervention methods; it is usable by supported applications without implementing the lifecycle substrate from scratch. - Why this is / is not agent-owned: the first-party runtime supplies the S3-specific view and intervention path but no standard autonomous supervisor was found that observes the whole pool and owns the discretionary portfolio/resource decision. Deterministic status transitions and limits are enforcement, not autonomous S3 ownership. - Evidence: packages/agent-management/src/runtime/AgentRuntime.ts, packages/agent-management/src/runtime/index.ts, packages/agent-management/src/runtime/schemas.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: the shipped coding agent&#39;s synchronous spawnagent delegation is not itself credited as autonomous S3 because it lacks a whole-current-pool supervisory loop. The C claim rests on the exported AgentRuntime constructor surface. - Whole-system current view: listAgents() can return the managed pool filtered by group/status/ephemeral state and getStats() summarizes the runtime population by status. - Current-control decision scope: create a new managed operational unit or stop one/all currently managed units, changing current commitments and resource occupancy.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party path establishes a sufficiently independent complementary auditor that challenges ordinary operational claims and closes findings back into corrective S1/S3 action. - Disturbance / variety regulated: not established as S3 at the reviewed runtime boundary. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: hooks can inspect/modify/cancel extension-point payloads, telemetry/logging records runtime activity, approval policy gates tools, and sub-agent progress reports ordinary subordinate execution. - Closure path: not applicable. - Why this is / is not agent-owned: the inspected mechanisms observe, gate or transport the normal production path; no independent complementary operational-reality judgment owner was found. - Evidence: packages/core/src/hooks/manager.ts, packages/core/src/hooks/types.ts, packages/core/src/telemetry/README.md, packages/agent-management/src/tool-factories/agent-spawner/runtime.ts. - Basis: structural absence review. - Confidence: medium-high. - Caveats: downstream applications can install hooks/evaluators, but generic extension capability is outside the positive constructor threshold unless the S3 function itself is supplied.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party path establishes an external-and-prospective adaptation loop that develops future-oriented options and closes them back into current capability. - Disturbance / variety regulated: not established as S4 at the reviewed boundary. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: persistent memory CRUD, skill creation/update tools, dynamic skill loading, web/search/tool access, configurable model/tool switching and ordinary current-task planning. - Closure path: not applicable. - Why this is / is not agent-owned: a model can write memories or create/update a skill when those tools are available, but the standard evidence reviewed does not supply the missing external/prospective distinction and adaptation-judgment loop; persistence/self-modification alone is not S4. - Evidence: packages/tools-lifecycle/src/memory-tools.ts, packages/agent-management/src/tool-factories/creator-tools/factory.ts, .agents/skills/create-skill/SKILL.md, docs/docs/architecture/skills.md. - Basis: structural absence review. - Confidence: medium-high. - Caveats: creator tools are strong capability-mutation primitives and could support an S4 design, but Methodology does not award C from generic self-modification primitives when the S4 function itself is not established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party runtime path establishes identity/ultimate-policy adjudication at the chosen Dexto harness recursion. - Disturbance / variety regulated: not established as S5. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: system prompts, YAML configuration, permission modes/tool policies, human tool approvals, agent registry/configuration, safety hooks and operator setup. - Closure path: not applicable. - Why this is / is not agent-owned: these surfaces define or enforce operating constraints and authorize current actions, but no identity/constitutional-policy issue → legitimate ultimate authority → authoritative decision → returned governing-policy loop was established. - Evidence: README.md, agents/coding-agent/coding-agent.yml, packages/core/src/agent/DextoAgent.ts, packages/core/src/hooks/types.ts. - Basis: structural absence review. - Confidence: medium-high. - Caveats: an operator can change configuration and approve risky tool actions, but generic operator authority/action approval is not automatically S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/034ced809fa7bcd5b44391285be13cd8ab3bed53/assessments/dexto.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 034ced809fa7bcd5b44391285be13cd8ab3bed53\">034ced8 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-20T22:11:16+03:00\"><th scope=\"row\"><a href=\"https://github.com/omnirexflora-labs/omnicoreagent\" target=\"_blank\" rel=\"noopener\">OmniCoreAgent</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/omnirexflora-labs/omnicoreagent/tree/60da57a6dacd3f7796fffd9d198c0a7420aa6aad\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 60da57a6dacd3f7796fffd9d198c0a7420aa6aad\">60da57a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously reason over an application request, choose tool/delegation/final-response actions, consume observations and produce the requested operational result. - Disturbance / variety regulated: open-ended user/application tasks, tool/API outcomes, errors, large/noisy outputs, context pressure, discovered information and changing intermediate task state. - Decisive decision or feedback right: choose the next substantive model/tool/delegation action and when to return the final task response within the configured harness contract. - Decision owner: the model-driven OmniCoreAgent execution loop. - Supporting / enforcement mechanisms: prompt builder, model transport, local/MCP tool registry, parallel tool runner, structured observation formatting, memory, context management, workspace/offloading, guardrails, loop signatures, telemetry and optional subagent factory. - Closure path: request/history → model decision → tool call(s) or delegated worker → structured observation/result → updated model context → subsequent model decision/final response. - Boundary reachability: OmniCoreAgent.run is the package&#39;s primary public entry point and directly builds/invokes the first-party runtime loop; it does not depend on a separate application implementing the operational feedback loop. - Why this is / is not agent-owned: deterministic runtime code executes and constrains actions, but the running model chooses the substantive next action based on observations and owns the task-level decision loop. - Evidence: README.md, OmniCoreAgent.run, subagents.py. - Basis: explicit + structural. - Confidence: high. - Caveats: dynamic subagents are credited as a mechanism available to S1; their mere existence does not imply S2 or S3 at a higher recursion.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material S2-specific inter-S1 conflict/oscillation attenuation path is established at the declared recursion. - Disturbance / variety regulated: not established as an S2 disturbance. - Decisive decision or feedback right: not established as S2. - Decision owner: not applicable. - Supporting / enforcement mechanisms: parallel tool batches, dynamic subagents, shared workspace output, sequential/parallel/router workflows and gathered results provide decomposition, routing and aggregation. - Closure path: subagent results return to the lead agent or workflow output, but this is delegation/composition rather than a demonstrated attenuation loop for interference between distinct S1 units. - Why this is / is not agent-owned: generic parallelism, routing and shared storage do not satisfy the S2 constructor threshold without a specific inter-S1 disturbance and coordination relation directed at it. - Evidence: README.md, subagents.py, cookbook/workflows/README.mdx. - Basis: structural negative finding. - Confidence: high. - Caveats: applications can compose multiple agents and workflow routers, but generic composition is intentionally insufficient for S2=C under Methodology 0.3.5.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no autonomous whole-system inside-and-now control function is established at the declared harness recursion. - Disturbance / variety regulated: runtime failures, repeated loops, expired leases, retry conditions, cancellation requests, budget/policy violations and service lifecycle conditions are handled, but not through an evidenced autonomous S3 owner. - Decisive decision or feedback right: no first-party autonomous actor is established as owning project/application-wide current allocation, priority, commitment or intervention decisions. - Decision owner: authored runtime/policy configuration and deterministic machinery for the inspected control surfaces; external callers/approval resolvers may own some configured choices. - Supporting / enforcement mechanisms: signature loop detection, max steps, background task state, leases/retries/recovery/cancellation, governance allow/deny/ask evaluation, budget accounting, sandbox requirements, request lifecycle and rate limits. - Closure path: these mechanisms can terminate/retry/block/serve configured operation, but they enforce previously selected rules or external commands rather than closing an autonomous whole-system S3 discretion loop. - Why this is / is not agent-owned: the lead model owns task-level S1 choices; the production control mechanisms around it are deterministic or externally authored and do not make the lead agent a whole-system regulator merely because it can delegate. - Evidence: README.md, background-agents architecture, GovernanceEngine. - Basis: structural negative finding. - Confidence: high. - Caveats: a developer can build a supervisory organization from the available primitives. General framework expressiveness is not a positive C state without an S3-specific autonomous decision path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent complementary audit function with corrective return is established in the standard harness boundary. - Disturbance / variety regulated: prompt injection, runtime errors and policy violations are screened/observed, but those checks are ordinary production safety/control mechanisms rather than an independent S3 challenge of S1 reporting. - Decisive decision or feedback right: not established as an independent audit judgment. - Decision owner: guardrail/policy/runtime machinery or application-authored policy, not a separate audit actor. - Supporting / enforcement mechanisms: guardrails, telemetry/traces, structured events, governance evaluation, loop detection, logs and background run history. - Closure path: safety checks can block ordinary execution and telemetry can expose evidence, but no distinct reviewer/challenger obtains complementary evidence, independently judges an S1 claim and returns findings into whole-system corrective control. - Why this is / is not agent-owned: observability and guardrails can be valuable verification mechanisms while remaining inside the ordinary production/control path; Methodology 0.3.5 requires complementary access, independence and findings-to-control closure for S3. - Evidence: README.md, governance/enforcement.py, engineering/architecture/telemetry.md. - Basis: structural negative finding. - Confidence: high. - Caveats: an application can consume traces and create an external reviewer, but that downstream composition is not credited to OmniCoreAgent itself.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no distinct prospective environment-facing adaptation loop is established at the assessed harness recursion. - Disturbance / variety regulated: not established at S4 scope. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: memory, context summarization, workspace persistence, skills, retrieval/MCP tools and background schedules can retain or retrieve information but do not by themselves select future capability adaptation. - Closure path: stored/retrieved information can affect later task reasoning, but no first-party loop senses future/environment distinctions, generates adaptation options and returns a selected capability/program change into current operation. - Why this is / is not agent-owned: remembering earlier messages, summarizing context, retrieving external information or loading a skill is not equivalent to S4 adaptation ownership. - Evidence: README.md, OmniCoreAgent runtime. - Basis: structural negative finding. - Confidence: high. - Caveats: application-specific agents can research the environment during S1 work; that task behavior does not establish a separate harness-level S4 function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity/ultimate-policy function is established at the assessed harness recursion. - Disturbance / variety regulated: application-authored capability, budget, approval and sandbox constraints regulate execution but are not evidenced as identity-level policy disputes. - Decisive decision or feedback right: not established as S5. - Decision owner: application/deployer-authored policy and optional approval resolver for the inspected governance path. - Supporting / enforcement mechanisms: PolicyEnvelope, allow/deny/ASK decisions, approval resolution, policy hashes, budget constraints, sandbox requirements, prompt contract and serving configuration. - Closure path: governance decisions can permit/block/ask for individual execution capabilities, but no identity/ultimate-policy issue is routed to an S5 authority and returned as governing identity policy for the system. - Why this is / is not agent-owned: a prompt contract, permission/capability policy, budget or human approval is not automatically S5; the policy objects regulate execution rights rather than the organization&#39;s identity/ultimate purpose at this recursion. - Evidence: governance/enforcement.py, README.md. - Basis: structural negative finding. - Confidence: high. - Caveats: the governance subsystem deliberately exposes application control; this assessment does not reinterpret operational authorization as S5 without identity-level evidence.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/60fa7f6cbad5d00ad76aac4e43ee85735aaa106f/assessments/omnicoreagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 60fa7f6cbad5d00ad76aac4e43ee85735aaa106f\">60fa7f6 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:15:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/openai/openai-agents-python\" target=\"_blank\" rel=\"noopener\">OpenAI Agents SDK</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/openai/openai-agents-python/tree/fbd2dbcaaf74a2c447c6d3fa9d5645d83fd7e292\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision fbd2dbcaaf74a2c447c6d3fa9d5645d83fd7e292\">fbd2dbc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: first-party agents autonomously select tools/actions and execute task work within application-defined bounds.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: handoffs and manager-to-specialist calls transfer/delegate work, but the SDK does not itself provide a function whose responsibility is regulating interference or shared constraints among multiple autonomous S1 units. The earlier S2=C interpretation is removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: a manager agent or code orchestrator assigns operational work but is not, by that fact, a whole-system current-control authority for resources/capacity/commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: evaluator loops are ordinary application composition over the same work product. No built-in independent/complementary audit channel with distinct organizational access/authority is established; the earlier S3=C interpretation is therefore removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: routing and orchestration concern current task execution, not a distinct prospective environmental intelligence function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: instructions, guardrails, handoff topology and application policy are developer-owned; the SDK does not supply autonomous ultimate policy/identity authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0b75c7fb0539831a89e5ca33f4cf1df430f3550f/assessments/openai-agents-sdk.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0b75c7fb0539831a89e5ca33f4cf1df430f3550f\">0b75c7f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-19T19:27:16+03:00\"><th scope=\"row\"><a href=\"https://github.com/smtg-ai/claude-squad\" target=\"_blank\" rel=\"noopener\">Claude Squad</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/smtg-ai/claude-squad/tree/ce1ffb4392b01f38e2c4599c7c84d2a93973b138\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ce1ffb4392b01f38e2c4599c7c84d2a93973b138\">ce1ffb4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously perform coding tasks that transform the target repository/environment inside a Claude Squad-managed session. - Disturbance / variety regulated: heterogeneous coding prompts, repository/file state, compilation/test/tool feedback and other task-local uncertainty encountered by the hosted autonomous coding agent. - Decisive decision or feedback right: choose the coding/tool actions required to satisfy the assigned prompt, observe resulting repository/tool state, and continue or finish the task. - Decision owner: the supported autonomous terminal coding-agent process (for example Claude Code, Codex, Gemini or Aider) running as the operational actor inside the Claude Squad-managed session. - Supporting / enforcement mechanisms: Claude Squad tmux lifecycle, prompt injection, per-session git branch/worktree, persisted session metadata, terminal/status capture, diff monitoring and optional automatic confirmation keystrokes. - Closure path: user assigns prompt → Claude Squad launches/sends it to the managed coding-agent process in its worktree → agent autonomously acts on code/tools and observes results → agent continues its local loop and produces repository changes/output visible through the session/diff surfaces. - Boundary reachability: hosting these agent programs is Claude Squad&#39;s documented standard product mode, not an adjacent example or developer workflow. The TUI directly starts the configured program in the first-party-created worktree and sends prompts to it, so the autonomous operational actor is reachable in the supported assembled distribution. - Why this is / is not agent-owned: removing the hosted coding-agent process while leaving tmux, worktree, persistence and TUI machinery leaves no actor that interprets the coding prompt and chooses repository-changing actions. Claude Squad supplies the harness around that autonomous S1 rather than owning the model&#39;s local decisions itself. - Evidence: README.md, session/instance.go, session/tmux/tmux.go, app/app.go. - Basis: explicit - Confidence: high - Caveats: Claude Squad does not own the external agent executable/model internals; only the operational actor&#39;s role in the intentionally assembled supported runtime is credited. No higher function is inferred from undocumented capabilities of those external agents.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: prevent destructive workspace/git-state interference among concurrent coding-agent S1 sessions operating on tasks in the same repository. - Disturbance / variety regulated: simultaneous agents writing files/index/worktree state in one shared checkout could overwrite, mix or otherwise conflict with one another&#39;s task-local repository changes. - Decisive decision or feedback right: assign each concurrent task/session an isolated branch/worktree before its agent starts, thereby selecting a non-shared mutable workspace for subsequent S1 actions. The first-party path is S2-specific, but an autonomous actor that decides or revises this coordination response is not supplied. - Decision owner: constructor-level. Claude Squad deterministically enforces per-session isolation under operator-created sessions; a deployment would need to compose an autonomous coordination actor/authority if it wanted agent-owned discretion over when/how to isolate, reconcile or revise the coordination response. - Supporting / enforcement mechanisms: unique worktree directory generation, per-session branch names, tmux startup with the worktree as -c working directory, branch preservation across pause/resume and later operator integration controls. - Closure path: concurrent task/session creation → Claude Squad creates distinct branches/worktrees → each coding-agent S1 is launched inside its assigned worktree → its later file/git writes remain separated from other active sessions&#39; mutable workspaces. - Boundary reachability: the isolation relation is mandatory first-party startup behavior in the normal multi-session product mode and is explicitly documented as the reason parallel tasks avoid conflicts; it does not depend on tests, CI or external agent internals. - Why this is / is not agent-owned: the S2 function and attenuation path are supplied, but the hosted agents do not choose or negotiate the coordination response. Deterministic isolation enforces a preselected policy; therefore it does not meet A, while the dedicated conflict-prevention path is more specific than generic routing/shared-state extensibility and meets the constructor threshold. - Distinct S1 units: at least two simultaneously managed autonomous coding-agent sessions, each assigned a separate coding task and worktree. - Inter-S1 disturbance: concurrent edits/git operations against one repository checkout would contend on shared mutable workspace/index/file state; the README states each task uses an isolated git workspace &quot;so no conflicts&quot;. - Attenuating coordination relation: Claude Squad creates a unique branch/worktree for every session and starts that agent&#39;s tmux program inside that isolated worktree. - Feedback into subsequent S1 behaviour: the selected isolation is embodied in each agent&#39;s working directory; all subsequent task-local file/git actions occur against that separated state rather than the other S1s&#39; workspaces. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the mechanism is explicitly tied to attenuating a named cross-worker collision mode caused by parallel repository modification. It does not receive credit merely because Claude Squad launches multiple processes or has a session list. - Evidence: README.md, session/git/worktree.go, session/instance.go, session/tmux/tmux.go. - Basis: explicit - Confidence: high - Caveats: isolation prevents one important collision class but does not constitute rich mutual adjustment or automated branch reconciliation. Human integration decisions are outside S2 parent notation and are not used to upgrade the constructor state.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-system current-control loop was established beyond session lifecycle management and fixed capacity/configuration constraints. - Disturbance / variety regulated: candidate paths included the global list of sessions, Running/Ready/Loading/Paused status, a fixed 10-instance limit, instance ordering, diff/preview panes, create/kill/pause/resume and push/checkout actions. - Decisive decision or feedback right: no agent or first-party S3-specific constructor was found that receives a whole-system current operational picture and decides shared resource allocation, commitment reprioritization, synergy or intervention on behalf of the multi-session whole. - Decision owner: none established for S3 at the assessed recursion. - Supporting / enforcement mechanisms: TUI list/status display, GlobalInstanceLimit, per-instance metadata/diff refresh, lifecycle commands, confirmations and tmux/worktree state. - Closure path: operator commands can change an individual session&#39;s lifecycle or integrate one branch, but no S3-specific whole-system regulation loop was found. - Why this is / is not agent-owned: showing several sessions and allowing a human to pause/kill/reorder one is management UI, not autonomous inside-and-now control. The hosted coding agents do not receive the whole-session view or authority to regulate the other sessions through Claude Squad. - Evidence: app/app.go, session/instance.go. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent first-party complementary audit loop with findings returned into subsequent operational control was established. - Disturbance / variety regulated: candidate evidence included the diff tab, terminal preview/history and the documented ability to review changes before applying/pushing them. - Decisive decision or feedback right: the human operator can inspect diffs and decide whether to push/checkout, but Claude Squad supplies no autonomous or constructor audit actor that independently challenges an S1 claim/result and returns a corrective finding into that S1&#39;s execution. - Decision owner: none established in the Methodology&#39;s S3 publication states. - Supporting / enforcement mechanisms: git diff computation/display, terminal capture, push confirmation and checkout/pause workflow. - Closure path: human inspection may lead to manual reprompting or refusal to integrate, but no first-party complementary audit judgment→corrective-return loop is encoded as an autonomous/constructor S3 path. - Why this is / is not agent-owned: review UI gives a human alternative access to artifacts, but Methodology 0.3.x does not publish parent-mode S3 and ordinary human review cannot be relabelled autonomous audit. - Evidence: README.md, app/app.go, session/instance.go. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party externally/prospectively oriented adaptation loop was established for changing Claude Squad&#39;s future operational capability. - Disturbance / variety regulated: candidate paths included multiple configurable agent profiles/programs, operator reprompting, persisted state, release/update mechanics and the ability to resume sessions. - Decisive decision or feedback right: no first-party path senses external/future distinctions, develops an adaptation option and returns it to alter the harness&#39;s capability for subsequent work. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: static profile configuration, program command selection, persistence and lifecycle controls. - Closure path: changing a profile/program selects an already available external agent command; it does not constitute prospective capability development by the harness. - Why this is / is not agent-owned: hosted coding agents adapt within their assigned coding tasks, but no Claude Squad metasystem actor studies the future/external environment and changes the harness&#39;s repertoire. - Evidence: README.md, config/config.go, app/app.go. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy decision path was established at the multi-session system recursion. - Disturbance / variety regulated: candidate paths included configuration profiles, --autoyes, trust-prompt handling, kill/push confirmations, branch selection and operator control of sessions. - Decisive decision or feedback right: no identity/ultimate-policy issue is escalated to an ultimate authority and returned as durable policy governing later operation. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: config file, profile/program choice, automatic confirmation behavior, TUI confirmation overlays, tmux trust-prompt handling and ordinary operator commands. - Closure path: confirmations affect individual operational actions; they do not close system identity/ultimate-policy tension at the declared recursion. - Why this is / is not agent-owned: the human has final say over ordinary push/kill/session actions, but final say on a task action is not S5. External coding agents&#39; system prompts/policies are outside Claude Squad ownership. - Evidence: README.md, app/app.go, session/tmux/tmux.go. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/74f026f79c2706a649d22ed8e01c785a180e8f0c/assessments/claude-squad.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 74f026f79c2706a649d22ed8e01c785a180e8f0c\">74f026f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/FoundationAgents/OpenManus\" target=\"_blank\" rel=\"noopener\">OpenManus</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/FoundationAgents/OpenManus/tree/3309bf4e416fb1c74b008f3e86494439a31bad53\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3309bf4e416fb1c74b008f3e86494439a31bad53\">3309bf4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: configured agents autonomously execute task steps with tools/model reasoning under the planning flow.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: sequencing and assignment of planned steps do not establish a dedicated interference-regulation mechanism among multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: plan status and agent dispatch manage the current workflow, but no whole-system current-control authority over shared organizational resources/commitments was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: plan/status checks are part of normal execution; no independent complementary audit channel with distinct access was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: the planner reasons about how to accomplish the present task. Under the profile, internal task planning is not S4 without prospective external-environment intelligence that changes system capability/strategy.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: mission, prompts, agents and policies are externally configured; no autonomous ultimate identity/value authority is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/openmanus.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/langchain-ai/langgraph-bigtool\" target=\"_blank\" rel=\"noopener\">LangGraph BigTool</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/langchain-ai/langgraph-bigtool/tree/0bb7f9227d349afa4d4207c6630e800658c80894\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0bb7f9227d349afa4d4207c6630e800658c80894\">0bb7f92 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the graph supports an autonomous agent that selects and executes tools iteratively against task feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: graph transitions and tool retrieval coordinate steps inside one operational process; no regulation of interference among multiple autonomous S1 units was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: registry/retrieval state and graph routing do not constitute whole-system current authority over resources/commitments across S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit function distinct from the normal agent/tool execution graph was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: tool retrieval adapts the immediate capability surface to the current task but does not scan an external future environment or adapt the organization over a prospective horizon.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: the registry, graph, prompts and tool policies are application-defined; no autonomous ultimate policy/identity function is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/langgraph-bigtool.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-10T16:09:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/Team-Commonly/commonly\" target=\"_blank\" rel=\"noopener\">Commonly</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-10\">2026-10-10</time></td><td class=\"review-ref\"><a href=\"https://github.com/Team-Commonly/commonly/tree/669889886a9436b8349e4e60e5197bab504909e8\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 669889886a9436b8349e4e60e5197bab504909e8\">6698898 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: run real model/tool/feedback sessions for installed native agents serving pod requests and updating pod messages/tasks/memory. - Disturbance / variety regulated: pod user requests, changing discussion context, returned tool outcomes, memory and local service errors. - Decisive decision or feedback right: which reply and allowed tool call to make in each native model turn, and whether to continue with additional tools. - Decision owner: the installed native agent&#39;s model-backed turn; Commonly supplies the actual bounded model-call/tool-result loop. - Supporting / enforcement mechanisms: runAgent, LiteLLM /chat/completions, allowlisted commonly tool dispatcher, AgentRun traces, message/claim constraints and caps. - Closure path: an addressed/scheduled native installation receives trigger → model chooses tool call → first-party dispatcher executes permitted tool → result enters message history → next model turn chooses subsequent action/response. - Boundary reachability: shipped native runtimeType:&#39;native&#39; installations are dispatched through first-party agentEventService to nativeRuntimeService when LiteLLM is configured; optional BYO seats are not needed to demonstrate the native loop. - Why this is / is not agent-owned: removing model calls leaves relay/DB handlers and deterministic tools but no discretionary content/operation decisions. - Evidence: nativeRuntimeService.ts; agentEventService.ts; task-clerk.ts; index.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: Native LiteLLM must be configured; BYO seats alone are not a first-party native model loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate duplicate or abandoned work by two distinct active seat agents receiving the same human pod message through first-party exclusive attention claims and bounded handoff. - Disturbance / variety regulated: multiple seat S1s may answer the same broad human message, produce duplicate/conflicting replies, or a dead/declining seat may leave it unattended. - Decisive decision or feedback right: determine which seat may own a message claim, make other seats stand down and select the next eligible wake target after an explicit decline. - Decision owner: first-party deterministic CAS lease/attention kernel plus preconfigured original wake-target set, not a packaged autonomous coordinator that adaptively decides agent selection. - Supporting / enforcement mechanisms: messageclaims transaction/lease with a single valid holder, decline history, handoff service and per-seat runtime claim/release paths. - Closure path: broadcast message produces potential seat wakeups → claim transaction grants one seat/denies other → loser stands down → winner processes, or explicitly declines → release/handoff enqueues next eligible original seat → next S1 acts while rejected seats do not. - Boundary reachability: native runtime attempts claims before model work and releases them at terminal; shipped local/CLI adapters also use the shared kernel, though their own external cognition is not credited to the kernel. - Why this is / is not agent-owned: the disturbance-specific first-party gate and returned handoff are real, but their selection policy is enforced by lease/CAS and configured targets, not autonomously chosen by a first-party S2 model actor; this is C, not A. - Evidence: messageClaimService.ts; messageClaimHandoffService.ts; nativeRuntimeService.ts; agentMentionService.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: A deterministic exclusive claim is a real S2-specific construction path, not agent-owned planning; seat-agent cognition and policy choice are not credited to the kernel.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: a legitimate human pod-member/operator sees the pod task portfolio and installed agents and can revise current assignments, statuses and commitments, returning those revisions to active work. - Disturbance / variety regulated: misallocated, stale or blocked pod tasks and changes to commitments/work priorities across seats. - Decisive decision or feedback right: human pod member with write authority can assign/reassign, change task status, dependency and scope, and push the new current commitments into agent notifications. - Decision owner: authorized human pod operator/member in the supported parent-governed task-board mode; not the native model or automated lease/scheduler. - Supporting / enforcement mechanisms: pod-scoped GET of full task set with lease states, PATCH task fields, membership write check, per-task update history, task event notifications, UI board. - Closure path: operator observes complete pod task board plus seat status → makes current-work allocation/status decision → authorized task PATCH commits changed assignment/status → notifyPodAgents and board events deliver feedback to operational seat agents. - Boundary reachability: the self-hosted web UI and backend task APIs ship as the supported human-in-the-loop pod control mode; all task changes are scoped to a pod and gated to writers. - Why this is / is not agent-owned: the model/tool loops and message claims do not autonomously aggregate and control the pod&#39;s full current commitments; in this supported mode the parent writer owns current task portfolio interventions. - Evidence: tasksApi.ts; V2PodBoard.tsx; taskEventService.ts; agentStateService.ts. - Basis: explicit + structural. - Confidence: medium. - Caveats: P refers only to the pod-scoped human task-board current-control loop; it does not infer organization-level governance for all pods or the maintainer community.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: a complementary audit of reported agent task completion by an independent access route; not established from reviewed surfaces. - Disturbance / variety regulated: incorrect completion reports, ungrounded answers or unverified PR/task artefacts. - Decisive decision or feedback right: not established: the inspected audit logs/task updates provide evidence and visibility but no separate challenge owner and independently returned correction path was reconstructed. - Decision owner: unresolved; human users can view records, but that alone is not a credited complementary audit system. - Supporting / enforcement mechanisms: task change history, AuditLog, and agent ensemble observers are available instrumentation/roles without a proven independent direct-source audit procedure. - Closure path: no concrete independent audit finding → controller correction → changed S1 path verified. - Boundary reachability: the reviewed runtime, task board, audit logging and ensemble turn scheduler do not suffice for positive credit; additional first-party modules might alter this. - Why this is / is not agent-owned: storage/observability and routine multi-agent conversation alone cannot substitute for a contrasting evidence-access/independent reviewer. - Evidence: agentEnsembleService.ts; tasksApi.ts; AuditLog.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: prospective external-environment sensing and adaptation of the pod&#39;s future operating capability remains unresolved. - Disturbance / variety regulated: new external requirements, provider/capability shifts and future team needs. - Decisive decision or feedback right: unproven; scheduled summaries, memories, marketplace/installables and heartbeats do not by themselves settle adaptation choices or close them back into present capability. - Decision owner: unknown. Users can install/configure seats and models can remember information, but the S4 decision loop is not evidenced. - Supporting / enforcement mechanisms: pod-summarizer, long-term memory, scheduler, installable app registry, config APIs. - Closure path: no witnessed external distinction → prospective option → legitimate decision → changed pod operational capability loop. - Boundary reachability: shipped native summaries and memory exist but have not been connected into a decisive prospective adaptation loop. - Why this is / is not agent-owned: a retrospective digest and static memory are not sufficient for agent-owned or parent-owned S4. - Evidence: schedulerService.ts; agentMemoryService.ts; index.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: whole-pod identity/ultimate-policy resolution, beyond permissions and individual operational approvals, remains unverified. - Disturbance / variety regulated: conflicts about ultimate pod purpose, legitimate authority and constitution of the shared organization. - Decisive decision or feedback right: operator owns pod configuration, membership and grants; operational action approvals exist, but no identity-level issue → authoritative decision → returned governing operation chain was reconstructed. - Decision owner: the human pod creator/operator owns configuration and grants; ownership of a function-specific S5 loop has not been established. - Supporting / enforcement mechanisms: membership roles, pod configuration, tool grants, approval/decision requests and their enforcement. - Closure path: tool-level and connector-grant approvals can change allowed actions, but they do not necessarily settle the ultimate identity/policy question of the pod. - Boundary reachability: supported self-hosted UI, pod and service-grant routes were inspected; no identity-level S5 mode is asserted. - Why this is / is not agent-owned: human-administered permissions are not automatically S5=P; no model-owned ultimate-identity authority demonstrated. - Evidence: grants.ts; decisionRequestService.ts; pods.ts; roomGrantService.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b900d7b45fa741f16191894f9788429f7af5b294/assessments/commonly.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b900d7b45fa741f16191894f9788429f7af5b294\">b900d7b &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/cloudflare/agents\" target=\"_blank\" rel=\"noopener\">Cloudflare Agents</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/cloudflare/agents/tree/46760e635ce9599add0abbfe6c1a34af0d5d44f1\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 46760e635ce9599add0abbfe6c1a34af0d5d44f1\">46760e6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: first-party agent instances can autonomously execute model/tool behavior over persistent state and scheduled/event-driven work.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: agent-to-agent calls, workflows and subagent composition provide communication/delegation, but no distinct function was found that regulates interference or shared constraints among autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: Durable Object lifecycle, routing and scheduling are runtime infrastructure. They do not establish whole-system managerial authority over operational commitments/resources in the VSM sense.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: observability/state persistence does not create an independent complementary audit channel; no such first-party organizational function was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: scheduling and event processing concern execution timing, not prospective environmental intelligence and adaptation of system capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: topology, tools, prompts, access and policies are application/developer supplied. No autonomous ultimate policy/identity function is included.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/cloudflare-agents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/huggingface/smolagents\" target=\"_blank\" rel=\"noopener\">smolagents</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/huggingface/smolagents/tree/30bb1161095dbae2271e6bc3cc4c219cc3897a57\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 30bb1161095dbae2271e6bc3cc4c219cc3897a57\">30bb116 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: tool/code agents autonomously choose and execute task actions within configured bounds.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: managed-agent delegation does not itself regulate interference among peer autonomous S1 units. No separate anti-conflict/anti-oscillation or shared-constraint coordination function was established; the earlier S2=C interpretation is therefore removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: a manager agent assigning work is still task execution. The reviewed runtime does not provide whole-system authority for current resource, capacity or commitment regulation across S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit channel separate from routine agent execution was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: agent planning and delegation operate on the current objective; no distinct prospective environmental intelligence function was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: prompts, tools, managed-agent topology and permissions are parent/developer configured rather than determined by an autonomous policy/identity authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/smolagents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-19T15:20:54+03:00\"><th scope=\"row\"><a href=\"https://github.com/balrog-ai/BALROG\" target=\"_blank\" rel=\"noopener\">BALROG</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/balrog-ai/BALROG/tree/b7afe79e3e4265811cfa985ed7c95c4d1a11e3f5\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b7afe79e3e4265811cfa985ed7c95c4d1a11e3f5\">b7afe79 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Decide and enact the next game action in an interactive episode, conditioned on observations and previous actions. - Disturbance / variety regulated: Changing mission/world state, partial observation, invalid/ineffective actions, terminal conditions and long-horizon task uncertainty. - Decisive decision or feedback right: The model-backed first-party agent selects the action returned by act(); the evaluator routes the validated action to the game and exposes the resulting next observation/reward. - Decision owner: The configured agent/model acting through the shipped AgentFactory and NaiveAgent / other real shipped agent modes. The external LLM supplies cognition to this wired first-party operating path, not independent higher-recursion control. - Supporting / enforcement mechanisms: Prompt/history builders, model API client/retries, evaluator episode iterator, environment action validator, save/logging and terminal-step limits. - Closure path: Observation + history → model-backed act() → extracted game action → environment validity check and step() → new observation/invalid-action feedback → subsequent act(). - Boundary reachability: The public python eval.py agent.type=naive ... command wires AgentFactory into EvaluatorManager.run(), which calls Evaluator.runepisode() and the first-party act() method for each step. Model inference is externally provided but the action/feedback path is standard packaged functionality, not a sample-only diagram. - Why this is / is not agent-owned: In supported model-backed modes the next action is selected on current observation/context by the agent&#39;s configured inference; deterministic evaluator logic enforces the action interface and reports world state but does not select the substantive action. - Evidence: eval.py; balrog/agents/init.py; balrog/agents/naive.py; balrog/agents/chainofthought.py; balrog/evaluator.py; balrog/config/config.yaml. - Basis: Explicit source control/feedback loop with configurable model-backed agent choice. - Confidence: High for shipped structural mode, not an experimental success-rate claim. - Caveats: dummy/illustrative demo or absent/nonfunctional external model does not by itself prove active agent ownership. This positive is for supported configured model-backed play, not benchmark orchestration.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No evidenced first-party regulation of interference among distinct independently viable game-playing S1 units. - Disturbance / variety regulated: Parallel episode workloads may share CPU/API budget or output directories, but the benchmark&#39;s partitioned tasks, worker queue and result aggregation do not demonstrate oscillatory inter-S1 conflict and adaptive damping into participating agents. - Decisive decision or feedback right: Multiprocessing queues and numworkers dispatch episodes according to preset researcher configuration; no separate coordination actor judges specific inter-S1 conflicts and returns corrective constraints. - Decision owner: EvaluatorManager deterministic scheduling/configured worker count, not an autonomous S2 agent. - Supporting / enforcement mechanisms: Task queues, results queue, episode identity, file paths and progress logging. - Closure path: Episode jobs run and results return to the evaluator, not an inter-agent interference → coordination decision → changed later behavior loop. - Why this is / is not agent-owned: Multiple benchmark episodes/workers are evaluation replicas, not the autonomous operational divisions whose interference S2 would regulate. - Evidence: balrog/evaluator.py; eval.py; balrog/config/config.yaml. - Basis: Bounded absence after inspecting shipped episode scheduler and first-party agent paths. - Confidence: High at the declared boundary. - Caveats: An external multi-agent gaming organization would require a separate assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-game-playing-organization current-control loop is established at the declared agent recursion. - Disturbance / variety regulated: Resource contention, stop conditions, task mix and experiment scheduling remain parameters of the external evaluator/researcher rather than operational decisions of an agent-owned whole-current executive. - Decisive decision or feedback right: The researcher configures workers, episodes, tasks, model; the evaluator deterministically executes, records and stops episodes. The agent chooses local game moves but not whole-system resource/commitment allocations. - Decision owner: Experiment configuration and scripted evaluator, outside credited S3 ownership. - Supporting / enforcement mechanisms: Hydra config, fixed limits, worker scheduler, saved run state and episode termination. - Closure path: No sensed whole-system current condition → legitimate S3 resource/intervention decision → returned operational adjustments. - Why this is / is not agent-owned: Having centralized visibility of benchmark progress or a maximum episode length is not S3 decisive authority. - Evidence: balrog/evaluator.py; balrog/config/config.yaml; eval.py. - Basis: Bounded negative for agent operating recursion. - Confidence: High for shipped modes. - Caveats: Researcher administration of benchmark infrastructure is not the assessed agent&#39;s first-party S3 parent mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independently corrective organizational audit with a return path into this agent cell is established. - Disturbance / variety regulated: Evaluator sees rewards, episode failures and action validity; these observations document task performance but do not constitute an auditor independently checking organizational claims and changing later operating regulation. - Decisive decision or feedback right: Environment validity correction is part of the ordinary game action loop; offline recorded scores/statistics are not independently owned audit judgments with corrective operational closure. - Decision owner: Environment rules and evaluator recordkeeping, not a separate autonomous complementary auditor. - Supporting / enforcement mechanisms: Episode CSV/JSON logs, scoring, invalid-action string feedback and summary table. - Closure path: No complementary independent inspection → audit verdict → accountable agent/controller corrective response. Environment observation feedback belongs to S1. - Why this is / is not agent-owned: Recording a score, parsing validity or writing telemetry is not an organizational audit with independent judgment and corrective authority. - Evidence: balrog/evaluator.py; eval.py; balrog/config/config.yaml. - Basis: Bounded negative after checking scoring, feedback and agent integration. - Confidence: Medium-high; only code-level evidence, no runtime attestation. - Caveats: External research audit of model behavior is outside this game-playing agent boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party external-prospective scan/option/selection/adoption loop updates future game-playing capability at the stated boundary. - Disturbance / variety regulated: Unseen future games may expose policy deficiencies, but the shipped first-party loop reacts inside each episode, while future policy/prompt changes belong to external authors or prepared demonstrations. - Decisive decision or feedback right: Fixed operator-set agent.type and ICL dataset determine which preexisting behavior scaffold is used; the game-playing agent does not decide to modify its own later operating capability based on future/environmental opportunity assessments. - Decision owner: Researcher/author supplies prompt, sample records, client and benchmark settings; first-party code loads them. - Supporting / enforcement mechanisms: History buffering, optional CoT, few-shot replay, demonstration selection and caching. - Closure path: Past fixed episodes may be inserted into a current prompt, but no observed external trend → proposed future adaptation → adopted persistent capability change → return into later operations is shown. - Why this is / is not agent-owned: Memory, in-episode plan refinement and preloaded demonstrations do not alone confer S4 organizational adaptation ownership. - Evidence: balrog/agents/fewshot.py; balrog/dataset.py; balrog/agents/chainofthought.py; balrog/evaluator.py; balrog/config/config.yaml. - Basis: Bounded source negative; specifically checked the shipped optional ICL mode. - Confidence: Medium-high at the declared boundary. - Caveats: A separately built online-learning controller using BALROG evaluation output would be a different system-in-focus.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party autonomous or operationally closed parent identity/ultimate-policy function for the game-playing organization. - Disturbance / variety regulated: Which environments, model/providers, prompts, eval goals and stopping rules define the experiment is set by upstream config/researchers outside an assessed runtime identity/policy-return organ. - Decisive decision or feedback right: Evaluated agent receives its configured role/task; its moves do not decide the identity/purpose or ultimate policy of the whole organization. - Decision owner: Researcher/maintainer/operator configures purpose and authority; no live first-party legitimate S5 decision/return process is established. - Supporting / enforcement mechanisms: Hydra config, static prompt instructions, environment mission and terminal control. - Closure path: No runtime identity/ultimate-policy case → legitimate authority → policy decision → return to subsequent game-playing operation; static startup settings alone do not provide a qualifying parent mode. - Why this is / is not agent-owned: Constraints and instructions limit S1 actions without a first-party S5 governance loop. - Evidence: balrog/config/config.yaml; eval.py; balrog/agents/init.py; balrog/agents/naive.py. - Basis: Bounded negative at the declared standard distribution. - Confidence: High for reviewed runtime, without external governance inference. - Caveats: Repository maintainers and external organizations may exercise policy rights over experiments but are not shipped parent closure of the assessed agent.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/63e7c851e91ad868c72dc318e860aefd7b6eb56f/assessments/ba/balrog.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 63e7c851e91ad868c72dc318e860aefd7b6eb56f\">63e7c85 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-18T19:32:34+03:00\"><th scope=\"row\"><a href=\"https://github.com/ag2ai/ag2\" target=\"_blank\" rel=\"noopener\">AG2</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/ag2ai/ag2/tree/3211bb19832049e7abe1a5742b6d177274bff723\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3211bb19832049e7abe1a5742b6d177274bff723\">3211bb1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A. - Function: autonomous agent loops perform the primary task transformation through model decisions and tool actions. - Disturbance / variety regulated: user/task uncertainty, model outputs, tool/environment feedback, persistent conversational state and task-local exceptions. - Decisive decision or feedback right: choose the next model/tool action and revise the trajectory from returned observations. - Decision owner: the model-driven Agent actor. - Supporting / enforcement mechanisms: stream/history, tool execution, middleware, response validation, optional knowledge/assembly, subtask tools and runtime cancellation. - Closure path: tool/model results are appended to the run/stream and enter later model requests, changing subsequent action. - Why agent-owned: first-party source defines Agent as the agentic unit that runs the model loop and invokes tools; the README describes the model deciding when to call tools. - Evidence: README and ag2/agent.py at the pinned revision. - Basis: explicit and structural. - Confidence: high. - Caveats: developer configuration constrains prompts/tools/providers, but the operational choice within those bounds remains model-owned.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C. - Distinct S1 units: two or more autonomous Agent instances participating in a Network discussion. - Specific inter-S1 disturbance: multiple participants share one conversational work channel and can otherwise attempt to speak out of sequence or stall an expected turn, producing conversational collision/oscillation and blocking progress. - Coordination relation: the first-party DiscussionAdapter snapshots participant order, exposes one expectednextspeaker, rejects any out-of-turn EVTEXT, rotates the expected speaker after each accepted message, and publishes turnwithin expectations for delayed turns. - Disturbance attenuation: deterministic Hub/adapter enforcement serializes the common conversational floor; expectation feedback can warn or hide a participant that fails to take its expected turn. - Decisive decision or feedback right: the supplied protocol determines which participant may speak next and whether an attempted send is admissible; the developer chooses to compose the agents into this discussion mode rather than an autonomous agent choosing the coordination rule. - Decision owner: first-party deterministic runtime / developer-composed channel protocol, not an autonomous coordinating agent. - Supporting / enforcement mechanisms: authoritative Hub state, channel WAL, adapter state folding, validation, expectation sweeper and violation handlers. - Closure path: accepted turns advance expectednextspeaker; rejected out-of-turn sends return a protocol error; expectation violations feed channel warnings/hiding back into later participant behavior. - Why this is S2-specific rather than generic messaging: the primitive is explicitly a multi-participant turn-taking regulator with an evidenced collision/stall mode and enforced feedback, not merely a mailbox/router/graph edge. The standard distribution supplies the regulation, but autonomous coordination ownership must still be composed, so the publication state is C, not A. - Evidence: Network overview and DiscussionAdapter implementation. - Basis: explicit and structural. - Confidence: high. - Caveats: conversation free-form messaging and generic workflow sequencing are not independently promoted to S2; the positive claim rests on the concrete discussion turn-regulation path.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: —. - Function finding: the Hub centralizes current network state and enforces rules, but no first-party actor/path was established that combines a whole-system current view with discretionary authority over shared resources, commitments, priorities, accountability or intervention on behalf of the organization as a whole. - Disturbance / variety regulated: access limits, inbox pressure, delegation depth, channel counts and TTLs are runtime constraints, not by themselves S3 organizational decisions. - Decisive decision or feedback right: not established for S3. The default RuleBasedArbiter applies tenant/developer-selected rules; custom HubArbiter subclasses are extension points whose S3 semantics, if any, belong to downstream composition. - Decision owner: not established. - Supporting / enforcement mechanisms: Hub health(), registry/channel state, Rule, RuleBasedArbiter, rate/inbox/access checks, TTL/expectation sweepers and HITL hooks. - Closure path: the runtime can allow/deny individual network actions and auto-close channels, but this closes enforcement decisions selected elsewhere rather than a first-party whole-system current-control loop. - Why not C: a generic/customizable policy gate plus central telemetry does not establish the S3 function before autonomy classification. The developer would need to supply the whole-system regulatory judgment itself, not merely its autonomous owner. - Evidence: Hub/Identity and Governance/Audit documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream application can implement an S3-capable arbiter or manager against these primitives; that composed system requires its own assessment boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: —. - Claim being audited: channel/rule/expectation events and operational state are recorded by the Hub audit/listener path. - Ordinary reporting path: the Hub&#39;s own registry, WAL, state transitions and expectation evaluators. - Complementary access path: none established. The built-in AuditLog is itself a Hub listener receiving the same committed transitions, and expectation evaluators inspect the same channel metadata/WAL state. - Independence boundary: no materially independent operational-evidence path is supplied by default. - Decisive audit judgment / owner: not established. - Supporting / enforcement mechanisms: append-only audit log, HubListener, expectation evaluators, task observations and custom listener hooks. - Closure path: expectation violations can warn/close channels, but that is ordinary protocol monitoring/enforcement rather than complementary independent audit. - Why not C: custom listeners/evaluators can be attached, but the standard distribution does not supply an S3-specific independent evidence/judgment path; generic extension is insufficient. - Evidence: Governance/Audit documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream independent auditor using different evidence could establish S3 in a composed system.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: —. - External distinction: agents can use tools and external services during current task execution. - Future/prospective distinction: no distinct first-party environmental/future model was established for organizational adaptation. - Adaptation option generated: none at the harness-organization capability level. - Path back into current capability / S3: none established. - Decision owner: not applicable. - Supporting mechanisms: persistent knowledge, history compaction/assembly, observed capability statistics, tools, middleware and application-defined workflows. - Closure path: those mechanisms alter context or record retrospective performance, but no outside-and-then adaptation loop is supplied. - Evidence: agent harness and Hub/Identity surfaces reviewed at the pin. - Basis: structural. - Confidence: high. - Caveats: learning, compaction, retrospective task statistics and current external tool use are not S4 by themselves.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: —. - Identity / ultimate-policy issue: no first-party runtime path was established for resolving identity/ultimate-policy tensions for the configured agent organization. - Ultimate authority: developers/operators select prompts, models, tools, passports, rules, auth adapters, channel manifests and HITL hooks; those configuration choices are not themselves a runtime S5 loop. - Decisive decision or feedback right: no identity/ultimate-policy issue-to-authority-to-return path was established. - Supporting / enforcement mechanisms: Passport, Rule, authentication, access/limit enforcement, system prompts and human approval hooks. - Return-to-operation path: ordinary HITL approval returns to the current tool trajectory, but the documented cases are task/safety approvals rather than identity-level policy closure. - Why not C or P: configurable policy/enforcement surfaces and generic human approval do not establish S5 before ownership is classified. - Evidence: Hub/Identity and HITL documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream organization may place ultimate policy at a human or institutional parent, but AG2 does not establish that function at this reviewed boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/dd2d14532e5ce959a06f0c4cb41677411cb03806/assessments/ag2.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit dd2d14532e5ce959a06f0c4cb41677411cb03806\">dd2d145 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/RooCodeInc/Roo-Code\" target=\"_blank\" rel=\"noopener\">Roo Code</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/RooCodeInc/Roo-Code/tree/b867ec9145750d0ae1ff7f02d35406e9bf2a0b16\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b867ec9145750d0ae1ff7f02d35406e9bf2a0b16\">b867ec9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the normal coding agent autonomously selects/executes tools and reacts to results inside configured permissions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: newtask is parent-to-child delegation. The reviewed implementation does not show a distinct function that regulates conflicts, oscillation or shared constraints between multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: parent task ownership and child-task lifecycle do not establish whole-system current authority over resources/commitments across multiple S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit path distinct from the normal operational hierarchy was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: mode selection and task decomposition are current-task planning, not a separate prospective environment-intelligence/adaptation function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: modes, permissions, rules and task goals are configured by the user/developer. No autonomous ultimate policy/identity authority is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/roo-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:01:12+03:00\"><th scope=\"row\"><a href=\"https://github.com/browser-use/browser-use\" target=\"_blank\" rel=\"noopener\">Browser Use</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/browser-use/browser-use/tree/50f205533fe10ba35b553d2a3689c77b87bd5d0a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 50f205533fe10ba35b553d2a3689c77b87bd5d0a\">50f2055 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the standard agent autonomously chooses browser/tool actions and continues from environment feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: no distinct mechanism was found for regulating interference among multiple autonomous S1 units. A single browser-agent loop with callbacks is not S2.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: run state, history and task-level planning manage one operational process; there is no whole-system current-control authority over multiple S1 commitments/resources.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the optional judge evaluates the operational trajectory/output inside the normal run. It is not evidenced as an organizationally independent or complementary audit channel with distinct access/authority.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: task planning predicts next actions for the current browser objective. No separate environment-scanning function that changes system capability or strategy over a longer horizon was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: tool permissions, task goals, prompts and approval/configuration remain externally supplied rather than owned by an autonomous policy/identity function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d3c36ab7c17230290253c004628399e193b7f685/assessments/browser-use.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d3c36ab7c17230290253c004628399e193b7f685\">d3c36ab &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:15:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/superagentxai/superagentx\" target=\"_blank\" rel=\"noopener\">SuperAgentX</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/superagentxai/superagentx/tree/28f2759f20d2dba9fa184ca4fe6b50943388cfbc\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 28f2759f20d2dba9fa184ca4fe6b50943388cfbc\">28f2759 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: individual configured agents autonomously execute model/tool work within the workflow.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: sequencing, routing, parallel fan-out and result aggregation define workflow topology, but no dedicated mechanism was found that detects and regulates interference or instability among multiple autonomous S1 units. Therefore the earlier workflow-derived C interpretation is rejected.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: workflow state and routing do not amount to a whole-system current-control function with authority over shared resources, priorities and commitments across the viable system.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: persistence, logging and ordinary review/approval stages remain part of the configured operational workflow; no independent complementary audit channel was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: routing and workflow planning concern present task execution, not a distinct prospective environment-scanning/adaptation function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: human approval and governance configuration are parent authority. The harness does not autonomously own ultimate identity, values or policy.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0b75c7fb0539831a89e5ca33f4cf1df430f3550f/assessments/superagentx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0b75c7fb0539831a89e5ca33f4cf1df430f3550f\">0b75c7f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-24T20:48:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/humanlayer/agentcontrolplane\" target=\"_blank\" rel=\"noopener\">Agent Control Plane</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-24\">2026-09-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/humanlayer/agentcontrolplane/tree/eaa2a7ed1d9cb4e13dc53defaf420e36f481dcad\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision eaa2a7ed1d9cb4e13dc53defaf420e36f481dcad\">eaa2a7e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform a durable goal-directed agent task through repeated model decisions and asynchronous tool/environment interactions until a final answer or terminal failure. - Disturbance / variety regulated: task/user objective, changing context window, available MCP/human/sub-agent tools, model-selected tool calls, asynchronous tool outcomes, transient model/tool failures and child/human completion latency. - Decisive decision or feedback right: choose the next substantive answer/tool action from the current Task context, then incorporate returned tool observations into the next semantic decision. - Decision owner: the configured ACP Agent&#39;s model-driven Task loop implemented by first-party Task/ToolCall controllers. - Supporting / enforcement mechanisms: durable Task/ToolCall CRDs, phase state machines, first-party LLM client factory, tool adapters/executor, per-Task mutex/Lease, controller-runtime reconciliation, context persistence, retries and terminal-state handling. - Closure path: Task objective/context → first-party Task controller sends context/tools to configured model → model chooses final content or tool calls → ACP creates first-party ToolCall resources → MCP/sub-agent/human path returns results → ACP appends tool messages to Task context → Task returns to ReadyForLLM → next model decision or final answer. - Boundary reachability: acp/cmd/main.go registers both Task and ToolCall reconcilers in the standard controller manager; TaskReconciler.SetupWithManager binds the Task CRD and initializes the production state machine. - Why this is / is not agent-owned: deterministic controllers enforce durable progression, but substantive next-action selection comes from the Agent&#39;s configured model over first-party-maintained context and tool choices. Human approval is optional for configured MCP tools and does not remove the standard autonomous operation path. - Evidence: acp/cmd/main.go; acp/internal/controller/task/taskcontroller.go; acp/internal/controller/task/statemachine.go; acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/toolcall/executor.go. - Basis: explicit + structural. - Confidence: high. - Caveats: external model inference, MCP servers and humans are dependencies. Their internal functions are not inherited; the positive S1 claim rests on ACP&#39;s first-party ownership of the iterative operational closure around them.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes regulation of a concrete disturbance between distinct ACP S1 operational units with feedback that changes their subsequent mutual behaviour. - Disturbance / variety regulated: ACP supports multiple Agents/Tasks and parent-to-child delegation, but the frozen standard distribution does not identify a specific inter-S1 collision, contention, contradictory commitment or shared-resource disturbance whose attenuation forms a closed coordination relation. - Decisive decision or feedback right: not established as a distinct S2 right. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: child Task creation, parent/child labels, child-result polling, Task-specific mutexes and Kubernetes Leases. - Closure path: delegation closes parent operation → child Task → child result → parent operation, which is task decomposition/recursion. The Task Lease closes duplicate controller execution for one Task. Neither path demonstrates inter-S1 disturbance → attenuation → feedback into multiple S1 units. - Boundary reachability: delegation and Task leases are standard-runtime code, but their organizational function is not S2 under the Profile criteria. - Why this is / is not agent-owned: multiple agents and delegation are topology. A controller lease is infrastructure consistency. Neither supplies the required coordination function merely because it affects concurrency. - Evidence: acp/internal/controller/toolcall/executor.go; acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/task/statemachine.go; acp/api/v1alpha1/agenttypes.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: an adopter can define interacting Agents/tools whose domain creates coordination needs. Such an instantiated organization would require separate evidence; ACP&#39;s generic delegation mechanism does not itself close S2. - Distinct S1 units checked: parent and child ACP Tasks/Agents created through the built-in delegation tool. - Inter-S1 disturbance checked: no first-party contract was found for branch/resource collision, contradictory shared commitments, rate/resource interference or another disturbance between those Tasks. - Why generic communication/routing/delegation is insufficient: the child result is simply returned as the result of the parent&#39;s selected tool call; no function-specific attenuation of mutual disturbance is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-system present-management loop is established across the running Agent/Task population. - Disturbance / variety regulated: individual Tasks are durably progressed and individual ToolCalls can be gated, retried or rejected; these controls do not provide a whole-current view with authority to allocate/reallocate resources or intervene across the operational organization as S3. - Decisive decision or feedback right: no first-party actor is shown receiving a whole-system current state and deciding present resource/work allocation or cross-unit intervention for the installation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: per-Task reconciler state, Task mutex/Lease, ToolCall approval, Agent/Task REST CRUD/list surfaces and Kubernetes controller manager. - Closure path: local Task state drives local reconciliation; configured human approval can decide whether one MCP call proceeds. No whole-system current-state → management judgment → intervention → changed organization-wide operation loop is established. - Boundary reachability: the cited local controls are standard runtime. Their presence is insufficient to change their organizational function into S3. - Why this is / is not agent-owned: durable supervision, retries, distributed locking and action approval are enforcement/operational mechanisms. No autonomous or parent current manager owns a whole-system S3 decision right at this boundary. - Evidence: acp/internal/controller/task/statemachine.go; acp/internal/controller/toolcall/statemachine.go; acp/api/v1alpha1/tasktypes.go; acp/internal/server/server.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: a user/operator can create, update or delete Agent definitions through API/Kubernetes surfaces, but generic administrative CRUD is not by itself a whole-current S3 function. - Whole-system current view checked: REST listing and Kubernetes resource observation expose state but no first-party current-management decision loop is bound to that view. - Current-control scope checked: no task priority, fleet quota, work reallocation or comparable whole-population management right was established in the reviewed Task/Agent contracts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material runtime path establishes an independent complementary audit of S1 operation with corrective return. - Disturbance / variety regulated: ACP records Kubernetes events/traces, validates resource dependencies and can require a human to approve a selected MCP call; these mechanisms observe or constrain the ordinary path but do not form a separate audit organization. - Decisive decision or feedback right: no independent auditor is shown judging operational claims/outcomes from materially complementary evidence and returning a corrective finding into subsequent operation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: status/events, OpenTelemetry spans, validation, human approval and repository-development review helpers outside the runtime boundary. - Closure path: runtime events/status support observability and approval may allow/reject a proposed tool call, but there is no independent audit finding → corrective action → re-observation loop over completed/ongoing work. - Boundary reachability: observability and approval are shipped; repository hack/ reviewer prompts are adjacent development material and excluded from runtime ownership. - Why this is / is not agent-owned: approval before an action executes is not complementary audit of operational reality, and telemetry does not own audit judgment merely because it records evidence. - Evidence: acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/task/statemachine.go; acp/cmd/main.go. - Basis: structural negative search. - Confidence: high. - Caveats: an Agent may be configured by an adopter to act as a reviewer, but role/prompt configuration does not establish a standard-distribution S3 function without evidence of independence and corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party prospective adaptation loop is established in the shipped runtime. - Disturbance / variety regulated: ACP reacts to current model/tool errors, dependency readiness, human responses and child-task results, but those are present operational observations rather than outside/future intelligence that changes the organization&#39;s future capability or strategy. - Decisive decision or feedback right: no runtime owner is shown generating/evaluating a prospective adaptation option and returning the chosen change into current organizational capability. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: durable context window, retries, MCP discovery, Agent validation, human-contact tools and external model/tool inputs. - Closure path: not established. Current observations return to the same Task loop as operational context; they do not become an organization-level prospective adaptation that changes how ACP subsequently operates. - Boundary reachability: reviewed first-party runtime code contains adapters and reactive controllers but no separate learning/adaptation owner/path. - Why this is / is not agent-owned: memory/context persistence and access to humans/external tools can support S1 cognition without constituting S4. Future-facing function must be proven separately. - Evidence: acp/internal/controller/task/statemachine.go; acp/api/v1alpha1/tasktypes.go; acp/api/v1alpha1/agenttypes.go. - Basis: structural negative search. - Confidence: high. - Caveats: an application built on ACP can create a research/adaptation Agent organization. That downstream composition is a separate system-in-focus.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy closure is established at the ACP installation recursion. - Disturbance / variety regulated: Agent system prompts, model/tool configuration, sub-agent lists and MCP approval settings constrain operational behaviour, while users/operators can create/update resources; none is shown recognizing and resolving an organizational identity/ultimate-policy issue as S5. - Decisive decision or feedback right: no first-party path establishes identity/policy issue → legitimate ultimate authority → authoritative decision → return governing subsequent operation. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: Agent system prompt, Agent/LLM/MCP resource configuration, optional approval contact channel, Kubernetes/API administration and human contact paths. - Closure path: configuration enters normal operation directly; configured approvals decide concrete ToolCalls. No distinct ultimate-policy feedback loop is established. - Boundary reachability: these configuration and approval surfaces are shipped and reachable, but their organizational function remains setup/action gating rather than S5 identity governance. - Why this is / is not agent-owned: system prompts and approval authority are not S5 by vocabulary or importance. The required identity/ultimate-policy closure is absent. - Evidence: acp/api/v1alpha1/agenttypes.go; acp/internal/controller/toolcall/executor.go; acp/internal/server/server.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: external Kubernetes administrators or application owners can act as ultimate authority in a wider organization, but generic platform administration is not automatically parent-owned S5 for ACP standalone.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/e4585aea9287dfa7097bfe057274632bc8ba2cae/assessments/humanlayer-agent-control-plane.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit e4585aea9287dfa7097bfe057274632bc8ba2cae\">e4585ae &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-21T19:01:50+03:00\"><th scope=\"row\"><a href=\"https://github.com/simular-ai/Agent-S\" target=\"_blank\" rel=\"noopener\">Agent S</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/simular-ai/Agent-S/tree/3aa272d23d2994c7bbde1acbbe0ef8e8d06b8693\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3aa272d23d2994c7bbde1acbbe0ef8e8d06b8693\">3aa272d &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform the requested computer-use transformation by observing the GUI, choosing the next task action, executing it through the first-party action interface, and continuing from returned environment state. - Disturbance / variety regulated: changing screen/application state, task-local uncertainty, action outcomes, tool/UI failures, prior trajectory context and, when enabled, returned local code-execution results. - Decisive decision or feedback right: choose the next substantive GUI/task action from the current instruction, screenshot and trajectory feedback. - Decision owner: the model-driven Agent S3 Worker operating inside the first-party AgentS3 runtime. - Supporting / enforcement mechanisms: AgentS3.predict, Worker history, task-local reflection, grounding/text-coordinate services, action format validation/parsing, pyautogui action generation, CLI screenshot/execute loop, and optional CodeAgent delegation. - Closure path: user task + current screenshot → Worker/model chooses a next action → Agent S converts the action into executable GUI code → CLI executes it against the desktop → changed screen state is captured → the new observation and prior trajectory/reflection enter the next Worker decision. - Boundary reachability: the shipped agents console entrypoint directly constructs AgentS3 and runs this screenshot→prediction→execution loop; no downstream adopter must invent the operational feedback path. - Why this is / is not agent-owned: deterministic parsing/grounding/runtime machinery constrains and executes actions, but the substantive next-action selection is made by the model-driven Worker from current environmental feedback rather than by a fixed script. - Evidence: setup.py; README.md; guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/cliapp.py; guiagents/s3/agents/grounding.py. - Basis: explicit + structural - Confidence: high - Caveats: external model and grounding providers remain execution dependencies, not credited first-party organizational owners. The optional CodeAgent can perform a bounded delegated coding subtask, but that does not change the primary S1 ownership claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct first-party S2 coordination function is established at the current Agent S3 runtime boundary. - Disturbance / variety regulated: no concrete interference, oscillation or conflict among two or more independently acting S1 units is established for the shipped S3 mode. - Decisive decision or feedback right: no S2-specific right to attenuate an evidenced inter-S1 disturbance is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: Worker→CodeAgent task/subtask delegation, task-local reflection, grounding/text helpers and sequential CLI execution were inspected but do not themselves constitute inter-S1 regulation. - Closure path: not applicable; the current runtime closes one primary Worker trajectory and optional subordinate delegation rather than a coordination loop among distinct S1s. - Why this is / is not agent-owned: the S2 function is not established before autonomy classification. AgentS3 explicitly removes hierarchy, and neither a delegated CodeAgent nor a reflection helper provides the required inter-S1 disturbance/attenuation/feedback witness. - Evidence: guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/agents/codeagent.py; guiagents/s3/agents/grounding.py; package entrypoint in setup.py. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established above the one Agent S3 operational trajectory. - Disturbance / variety regulated: current-task execution failures, step limits and CodeAgent budgets are handled within S1/runtime enforcement, not as whole-organization resource/commitment regulation. - Decisive decision or feedback right: no actor is shown holding a whole-system current view plus discretionary authority over multiple S1 commitments, priorities, resources, accountability or intervention. - Decision owner: not established. - Supporting / enforcement mechanisms: the CLI&#39;s finite step loop, Worker trajectory state, CodeAgent budget, pause/quit debugging path and task completion/failure signals provide execution control but not an S3 organizational decision right. - Closure path: not applicable; current state feeds the same Worker S1 or deterministic runtime termination rather than a separate S3 controller that returns portfolio-level decisions. - Why this is / is not agent-owned: no S3 function is established before autonomy classification. An enclosing loop or numeric budget is enforcement, and the current S3 source intentionally lacks the manager hierarchy that might otherwise be investigated for a higher-recursion current-control actor. - Evidence: guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/cliapp.py; guiagents/s3/agents/codeagent.py. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent complementary audit loop is established in the credited Agent S3 operating mode. - Disturbance / variety regulated: reflection can catch task-local mistakes and bBoN can compare completed rollouts, but neither establishes a qualifying independent audit-and-correction function for the standard live runtime. - Decisive decision or feedback right: no first-party auditor in the credited mode is shown independently validating an ordinary operational claim through a materially separate evidence path and returning a binding/corrective finding into subsequent operation. - Decision owner: not established. - Supporting / enforcement mechanisms: Worker&#39;s reflection agent, ordinary screenshots/action history, stored bBoN rollout result directories, fact captions and comparative judge. - Closure path: reflection advice returns inside the ordinary Worker trajectory; bBoN selects among already-produced rollout directories in an adjacent evaluation path. Neither establishes the required complementary-access audit closure at the declared runtime boundary. - Why this is / is not agent-owned: the function is not established before autonomy classification. Reflection sees the same task instruction, prior Worker action history and current screenshot used by ordinary operation, while bBoN is explicitly outside the ordinary CLI and no live corrective return from its post-hoc selection is evidenced. - Evidence: guiagents/s3/agents/worker.py; guiagents/s3/bbon/comparativejudge.py; README.md; osworldsetup/s3/bbon/ inspected as benchmark/evaluation support. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no distinct outside-and-then organizational intelligence/adaptation loop is established for Agent S3. - Disturbance / variety regulated: current screenshots and task feedback regulate present execution; they are not a prospective model of the external environment used to adapt future Agent S capability. - Decisive decision or feedback right: no first-party actor is shown generating a future-facing adaptation option from external change and installing/returning that option into current organizational capability. - Decision owner: not established. - Supporting / enforcement mechanisms: static procedural-memory prompts, current task trajectory, reflection, GUI observations, model/grounding configuration and benchmark/evaluation artifacts. - Closure path: not applicable; current-task evidence changes later actions within the same S1 trajectory, while static prompts and benchmark results do not form a shipped prospective adaptation-and-return loop. - Why this is / is not agent-owned: the S4 function is absent. Memory naming, reflection, external-screen perception and benchmark improvement claims do not by themselves establish future/environmental intelligence that changes the harness&#39;s subsequent capability. - Evidence: guiagents/s3/memory/proceduralmemory.py; guiagents/s3/agents/worker.py; README.md; S3 bBoN/evaluation surfaces. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established for the Agent S3 organization. - Disturbance / variety regulated: user task choice, provider/model/grounding configuration, local-env enablement, pause/quit controls and warnings constrain ordinary execution but do not resolve identity-level policy tensions. - Decisive decision or feedback right: no actor is shown receiving an identity/ultimate-policy issue, exercising legitimate ultimate authority over it, and returning an authoritative policy decision that governs subsequent Agent S operation. - Decision owner: not established. - Supporting / enforcement mechanisms: user-supplied task and configuration, CLI flags, safety warning for arbitrary local code execution, runtime pause/quit debugging control and external parent wrappers. - Closure path: not applicable; configuration and operator controls set or interrupt ordinary operation rather than close an identity/ultimate-policy loop. - Why this is / is not agent-owned: the S5 function is not established before autonomy classification. Prompts/configuration, static safety warnings, user invocation and an external OpenClaw parent are constraints or composition surfaces rather than Agent S-owned ultimate-policy authority. - Evidence: README.md; guiagents/s3/cliapp.py; integrations/openclaw/README.md; S3 procedural-memory prompts. - Basis: explicit + structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b6babf55bb8b8628646d733f30c5fd02d69d316b/assessments/agent-s.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b6babf55bb8b8628646d733f30c5fd02d69d316b\">b6babf5 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-27T00:43:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/Reason-Wang/ToolGen\" target=\"_blank\" rel=\"noopener\">ToolGen</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-27\">2026-09-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/Reason-Wang/ToolGen/tree/6839374a255810efe69deea4056eec5c55e25802\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6839374a255810efe69deea4056eec5c55e25802\">6839374 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform the user&#39;s substantive tool-using task through iterative model-selected actions, external tool effects/queries and result-conditioned next-action decisions. - Disturbance / variety regulated: open-ended user requests; very large available tool space; uncertainty about which API/tool fits the current subproblem; action-argument requirements; returned data; invalid/hallucinated action names; external API failures/timeouts/rate limits; incomplete information requiring additional calls. - Decisive decision or feedback right: choose the next task-relevant action/tool and its arguments from the live conversation/observations, interpret returned tool evidence/errors, and decide whether to take another action, answer, or abandon/restart the attempt. - Decision owner: the first-party model-driven ToolGen OpenAgent path. - Supporting / enforcement mechanisms: constrained action-token decoding, tool-token/name conversion, tool documentation lookup, SingleChainAgent state/tree, first-party action dispatch, RapidAPI/StableToolBench transport, observation truncation, status codes and maximum-chain-depth pruning. - Closure path: user task/current conversation -&gt; ToolGen model generates plan/action token/arguments -&gt; SingleChainAgent.takeaction() executes through the tool-state wrapper -&gt; external tool result/status returns -&gt; observation is appended to model context -&gt; later model call changes the next action or terminates -&gt; task progresses toward a final answer. - Boundary reachability: the README&#39;s standard local example directly constructs ToolGen plus RapidAPIWrapper, calls restart() and start(), which reaches the credited SingleChainAgent.dochain() / parse() / takeaction() loop without requiring the repository&#39;s training or evaluation programs. - Why this is / is not agent-owned: deterministic code constrains and executes the available interfaces, while the model selects the task-specific tool/action, generates its arguments and decides what follows from each returned observation. Removing the model decision path while leaving the wrapper/tool metadata in place would not produce materially the same operational choices. - Evidence: README.md; OpenAgent/agents/base.py; OpenAgent/agents/toolgen/toolgen.py; OpenAgent/tools/src/rapidapi/rapidapi.py. - Basis: explicit + structural. - Confidence: high. - Caveats: actual tool effects depend on external ToolBench/StableToolBench/API services. Those dependencies supply environmental capability/execution but do not select the contextual operational action credited to ToolGen.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no qualifying inter-S1 coordination function is established at the one-agent task boundary. - Disturbance / variety regulated: none qualifying; multiple callable tools/APIs create action-choice variety but are not independently accountable first-party operational S1 units whose interaction creates a conflict/oscillation/interference problem. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: action-token constraints, tool lookup/routing, sequential tool calls and shared conversation state are present but do not establish S2. - Closure path: no material inter-S1 disturbance -&gt; coordination decision -&gt; changed affected-S1 behaviour path closes. - Why this is / is not agent-owned: tool selection/routing and sequencing belong to one S1&#39;s task execution; they are not an organizational coordination relation among distinct operations. - Evidence: OpenAgent/agents/base.py; OpenAgent/agents/toolgen/toolgen.py. - Basis: structural absence. - Confidence: high. - Caveats: large tool cardinality does not itself imply a population of S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct superior whole-system current-control function is established above the single ToolGen task operation. - Disturbance / variety regulated: chain depth, status/error conditions and current tool results affect the current run, but these are either deterministic enforcement or ordinary S1 feedback. - Decisive decision or feedback right: no separate actor forms a whole-system current view and exercises discretionary authority over shared resources, commitments, priorities, constraints or multiple operational units. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: maximum step limit, tree/prune state, success/status codes, action constraints and process/runtime bookkeeping. - Closure path: deterministic bounds enforce configured limits while the same S1 model chooses task actions; no superior current-management feedback loop closes. - Why this is / is not agent-owned: SingleChainAgent is an orchestrator in the software sense, but its whole-run controls are pre-authored loop/stopping mechanics. The contextual decisions it carries are the S1 action choices, not a separately evidenced S3 management function. - Evidence: OpenAgent/agents/base.py; OpenAgent/tools/base.py. - Basis: structural absence. - Confidence: high. - Caveats: deterministic enforcement must not be promoted to S3 ownership merely because it controls execution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no qualifying complementary and sufficiently independent audit path is established in the standard OpenAgent runtime. - Disturbance / variety regulated: invalid action names, API/tool errors and external failures are observed and can change later S1 behavior, but they arrive through the ordinary action/observation channel. - Decisive decision or feedback right: no separately situated auditor independently checks operational reality and returns corrective findings into the task loop. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: wrapper status codes, tool observations, invalid-action handling and repository evaluation/pass-rate/preference programs. - Closure path: ordinary tool execution -&gt; ordinary tool observation/status -&gt; same S1 model chooses next action; adjacent evaluation programs produce benchmark measurements rather than corrective runtime audit closure. - Why this is / is not agent-owned: error observation and benchmark evaluation are valuable verification surfaces, but S3 requires complementary independent access and corrective feedback, not normal S1 observations or post-hoc scoring. - Evidence: OpenAgent/agents/base.py; OpenAgent/tools/src/rapidapi/rapidapi.py; README.md. - Basis: explicit + structural absence. - Confidence: high. - Caveats: evaluation infrastructure is adjacent to the runtime boundary and is not wired as an independent corrective auditor for live ToolGen operation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no qualifying external-and-prospective adaptation loop that changes installed/current organizational capability is established in the supported runtime. - Disturbance / variety regulated: the large external tool universe and returned information create current-task choice variety, while training processes can change future model capability offline; neither closes runtime S4 at this boundary. - Decisive decision or feedback right: no runtime actor is shown sensing longer-horizon external conditions, generating a capability/posture adaptation option and adopting it back into current ToolGen capability. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: action-token/tool retrieval, tool documentation, tool virtualization, memorization/retrieval/agent training, downloadable tool metadata and evaluation results. - Closure path: runtime tool retrieval selects a means for the current task; offline training changes checkpoints before deployment. No supported live external sensing -&gt; prospective adaptation option -&gt; changed installed/current capability loop closes. - Why this is / is not agent-owned: selecting among already available tools in response to the current query is S1 action selection. Training/tool memorization/retrieval training are developer/research processes outside the assessed operating mode and do not become S4 merely because they improve future performance. - Evidence: README.md; OpenAgent/agents/toolgen/toolgen.py; repository training/ and evaluation/ boundaries documented in the README. - Basis: explicit + structural absence. - Confidence: high. - Caveats: a future runtime that autonomously changes/persists its tool repertoire or model strategy from environmental evidence would require reassessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy authority is established. - Disturbance / variety regulated: user objective, system prompt, checkpoint, indexing method, configured tool universe, credentials, external service endpoint and chain limit constrain behavior but are supplied by operator/developer/configuration. - Decisive decision or feedback right: define or revise the ultimate purpose/identity/top-level policy governing the ToolGen organization independently of the supplied task/configuration. - Decision owner: external user/developer/configuration; no qualifying runtime S5 owner is established. - Supporting / enforcement mechanisms: static system prompt, model/checkpoint selection, tool-token mapping, API credentials, service URL and maximum-step configuration. - Closure path: no runtime identity/policy issue -&gt; authoritative S5 decision -&gt; changed operational policy loop closes. - Why this is / is not agent-owned: ToolGen decides how to pursue the supplied user task with configured tools, not what ultimate organizational identity/purpose it should adopt. - Evidence: README.md; OpenAgent/agents/toolgen/toolgen.py; OpenAgent/agents/base.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: the static AutoGPT-style system prompt and Finish contract are behavioral constraints, not a runtime S5 authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7d251ac32ca02e836b487a62eb71d305c3315733/assessments/toolgen.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7d251ac32ca02e836b487a62eb71d305c3315733\">7d251ac &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:01:12+03:00\"><th scope=\"row\"><a href=\"https://github.com/i-am-bee/beeai-framework\" target=\"_blank\" rel=\"noopener\">BeeAI Framework</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/i-am-bee/beeai-framework/tree/6a8b28f54073790f9a8135320a0e9ed1d4cef602\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6a8b28f54073790f9a8135320a0e9ed1d4cef602\">6a8b28f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: agents independently reason and use tools toward outcomes.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: first-party handoff/workflow mechanisms decompose or route work rather than provide mutual adjustment/collision regulation among autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the main agent chooses specialists during its own task but no whole-system current commitment/resource regulator is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: observability, middleware and requirement checking do not instantiate a distinct independent audit channel with corrective authority.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, RAG and environment tools serve current-task reasoning rather than a prospective intelligence loop coupled back to S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: RequirementAgent rules, tools, prompts and workflow policy are configured constraints, not autonomous ultimate-policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d3c36ab7c17230290253c004628399e193b7f685/assessments/beeai-framework.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d3c36ab7c17230290253c004628399e193b7f685\">d3c36ab &#8599;</a></td></tr>"];
